@Component("creditor-entity-projector")
public class CreditorEntityProjector implements EntityProjector<Creditor>{
		
	// core constructor
	public CreditorEntityProjector(ProjectorRegistry registry,
										CreditorRepository repository ) {
        this.registry 	= registry;
		this.repository = repository;
    }

	@Override
	public Class<Creditor> getEntityClass() {
		return Creditor.class;
	}

    /*
	 * Insert a Creditor
	 * 
     * @param	entity Creditor
     */
    public Creditor create( Creditor entity) {
	    LOGGER.info("creating " + entity.toString() );
	   
    	// ------------------------------------------
    	// persist a new one
    	// ------------------------------------------ 
	    return repository.save(entity);
        
    }

	/*
	 * Update a Creditor
	 * 
     * @param	entity Creditor
     */
    public Creditor update( Creditor entity) {
	    LOGGER.info("updating " + entity.toString() );

	    // ------------------------------------------
    	// save with an existing instance
    	// ------------------------------------------ 
		return repository.save(entity);

    }
    
	/*
	 * Delete a Creditor
	 * 
     * @param	id		UUID
     */
    public Creditor delete( UUID id ) {
	    LOGGER.info("deleting " + id.toString() );

    	// ------------------------------------------
    	// locate the entity by the provided id
    	// ------------------------------------------
	    Creditor entity = repository.findById(id).get();
	    
    	// ------------------------------------------
    	// delete what is discovered 
    	// ------------------------------------------
    	repository.delete( entity );
    	
    	return entity;
    }    


    /*
     * Add to the Mandates
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Creditor
     */
    public Creditor addToMandates( UUID parentId, DirectDebitMandate addTo ) {
	    LOGGER.info("handling AssignMandatesToCreditorEvent - " );
	    
	    Creditor parentEntity = repository.findById(parentId).get();
	    DirectDebitMandate child = registry.project( DirectDebitMandate.class, addTo.getDirectDebitMandateId());
	    
	    parentEntity.getMandates().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Mandates
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Creditor
     */
	public Creditor removeFromMandates( UUID parentId, DirectDebitMandate removeFrom ) {
	    LOGGER.info("handling RemoveMandatesFromCreditorEvent " );
	
	    Creditor parentEntity = repository.findById(parentId).get();
	    DirectDebitMandate child = registry.project( DirectDebitMandate.class, removeFrom.getDirectDebitMandateId());
	    
	    parentEntity.getMandates().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Creditor via an FindCreditorQuery
     * @return 	query	FindCreditorQuery
     */
    @SuppressWarnings("unused")
    public Creditor find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Creditor - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Creditors
     *
     * @param	query	FindAllCreditorQuery 
     * @return 	List<Creditor> 
     */
    @SuppressWarnings("unused")
    public List<Creditor> findAll( FindAllCreditorQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Creditor - {0}", exc.getMessage() );
    	}
    	return null;
    }


    //--------------------------------------------------
    // attributes
    // --------------------------------------------------
	@Autowired
    protected final CreditorRepository repository;
	protected final ProjectorRegistry registry;


    private static final Logger LOGGER 	= LoggerFactory.getLogger(CreditorEntityProjector.class.getName());

}
